// ── Two's complement negation (8-bit simulation) ──────────────
function negate8(n) {
  // Step 1: invert all bits (~n in JS is 32-bit, mask to 8)
  // Step 2: add 1, mask to 8 bits
  return ((~n) + 1) & 0xFF;
}

console.log('+5  =', (5).toString(2).padStart(8, '0'));          // 00000101
console.log('-5  =', negate8(5).toString(2).padStart(8, '0'));   // 11111011
console.log('-1  =', negate8(1).toString(2).padStart(8, '0'));   // 11111111
console.log('-128=', negate8(128).toString(2).padStart(8, '0')); // 10000000 (same!)

// ── Verify −5 + 5 = 0 ─────────────────────────────────────────
const neg5 = negate8(5);   // 0xFB = 251 as unsigned
const sum  = (neg5 + 5) & 0xFF;
console.log('-5 + 5 (8-bit) =', sum); // 0 ✓

// ── Signed 8-bit overflow: 127 + 1 wraps to -128 ─────────────
function addI8(a, b) {
  const raw = a + b;
  // Reinterpret 8-bit pattern as signed (sign-extend bit 7)
  return (raw & 0xFF) << 24 >> 24;
}
console.log('127 + 1 (int8)  =', addI8(127, 1));  // -128  ← overflow!
console.log('100 + 100 (int8)=', addI8(100, 100)); // -56   ← overflow!

// ── Unsigned 8-bit overflow ───────────────────────────────────
function addU8(a, b) { return (a + b) & 0xFF; }
console.log('255 + 1 (uint8) =', addU8(255, 1));   // 0     ← wraps
console.log('200 + 100 (uint8)=', addU8(200, 100)); // 44   ← wraps

// ── The famous 0.1 + 0.2 problem ──────────────────────────────
console.log(0.1 + 0.2);              // 0.30000000000000004
console.log(0.1 + 0.2 === 0.3);      // false
console.log((0.1).toPrecision(20));  // 0.10000000000000000555
console.log((0.2).toPrecision(20));  // 0.20000000000000001110
console.log((0.3).toPrecision(20));  // 0.29999999999999998890

// ── Safe comparison strategies ─────────────────────────────────
// 1. Absolute epsilon (only meaningful for values near 1.0)
const eps = Number.EPSILON;
console.log(Math.abs(0.1 + 0.2 - 0.3) < eps); // true

// 2. Relative tolerance (scales with magnitude)
function nearEqual(a, b, relTol = 1e-9) {
  return Math.abs(a - b) <= relTol * Math.max(Math.abs(a), Math.abs(b));
}
console.log(nearEqual(0.1 * 3, 0.3));                    // true  (0.1*3 is 0.30000000000000004)
console.log(Math.abs((1e16 + 2) - 1e16) < eps);          // false — at 1e16 doubles are 2 apart,
console.log(nearEqual(1e16 + 2, 1e16));                  // true  — so only a relative test works
console.log(nearEqual(1, 1.001));                        // false — genuinely different
console.log(1e16 + 1 === 1e16);                          // true  — the +1 is rounded away

// ── MAX_SAFE_INTEGER: where integers lose exact representation ──
console.log(Number.MAX_SAFE_INTEGER);            // 9007199254740991
console.log(Number.MAX_SAFE_INTEGER + 1);        // 9007199254740992
console.log(Number.MAX_SAFE_INTEGER + 1 === Number.MAX_SAFE_INTEGER + 2); // true!

// ── Money: store as integer cents to avoid float errors ─────────
const priceInCents = 199;   // $1.99
const taxInCents   = 16;    // $0.16
const totalCents   = priceInCents + taxInCents; // 215 (exact)
console.log('Total: $' + (totalCents / 100).toFixed(2)); // $2.15 (display only)

// ── Special IEEE 754 values ────────────────────────────────────
console.log(1 / 0);    // Infinity
console.log(-1 / 0);   // -Infinity
console.log(0 / 0);    // NaN
console.log(NaN === NaN);  // false! NaN is never equal to itself
console.log(Number.isNaN(NaN)); // true (safe check)

// ── Endianness and reinterpreting bytes with DataView ─────────
const buf = new ArrayBuffer(4);
const view = new DataView(buf);

view.setUint32(0, 0x12345678);              // DataView defaults to BIG-endian
console.log([...new Uint8Array(buf)].map(b => b.toString(16))); // [ '12', '34', '56', '78' ]

view.setUint32(0, 0x12345678, true);        // true = little-endian
console.log([...new Uint8Array(buf)].map(b => b.toString(16))); // [ '78', '56', '34', '12' ]

// Typed arrays use the HOST order — little-endian on x86 and ARM machines
console.log(new Uint32Array(buf)[0].toString(16));              // '12345678'

// Same 4 bytes, different interpretations
view.setInt32(0, -1);
console.log(view.getUint32(0));             // 4294967295 (all ones as unsigned)
console.log(view.getInt8(0));               // -1         (one byte, sign-extended)
view.setFloat32(0, 0.1);
console.log(view.getUint32(0).toString(16)); // '3dcccccd' — the IEEE 754 bits of 0.1f
